from pathlib import Path
from zipfile import ZipFile
import xml.etree.ElementTree as E
import json
N={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def read(p):
 with ZipFile(p) as z:
  strings=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   strings=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',N)]
  st=E.fromstring(z.read('xl/styles.xml'))
  fm={int(x.get('numFmtId')):x.get('formatCode') for x in st.findall('s:numFmts/s:numFmt',N)}
  xf=[int(x.get('numFmtId')) for x in st.findall('s:cellXfs/s:xf',N)]
  sheets=[]
  wb=E.fromstring(z.read('xl/workbook.xml'))
  names=[x.get('name') for x in wb.findall('s:sheets/s:sheet',N)]
  for i,name in enumerate(names,1):
   root=E.fromstring(z.read(f'xl/worksheets/sheet{i}.xml')); cells={}
   for c in root.findall('.//s:sheetData/s:row/s:c',N):
    v=c.find('s:v',N); val=v.text if v is not None else None
    t=c.get('t'); fmtid=xf[int(c.get('s','0'))]
    if t=='s': val=strings[int(val)]
    elif t=='inlineStr': val=''.join(c.find('s:is',N).itertext())
    elif val is not None:
     try: val=float(val) if '.' in val else int(val)
     except ValueError: pass
    cells[c.get('r')]={'value':val,'type':t or 'n','format':fm.get(fmtid,f'builtin:{fmtid}')}
   sheets.append({'name':name,'cells':cells,'conditionalFormatting':len(root.findall('s:conditionalFormatting',N)), 'merges':[x.get('ref') for x in root.findall('s:mergeCells/s:mergeCell',N)],'comments_parts':[n for n in z.namelist() if 'comment' in n.lower()]})
  return sheets
all_data={p.name:read(p) for p in sorted(Path('.').glob('*.xlsx'))}
Path('evidence/cells.json').write_text(json.dumps(all_data,ensure_ascii=False,indent=2))
for f,ss in all_data.items():
 print('\\nFILE',f)
 for s in ss:
  print('SHEET',s['name'],'conditionalFormatting',s['conditionalFormatting'],'comments',s['comments_parts'])
  for co,c in s['cells'].items():
   if c['value'] is not None: print(co,repr(c['value']),repr(c['format']))
