import json,re
from collections import Counter
D=json.load(open('evidence/cells.json'))
def row(co): return int(re.search(r'\\d+',co)[0])
for year in [2018,2020,2022,2023,2024,2025]:
 s=D[f'kyosei_{year}_37.xlsx'][0]; c=s['cells']
 print(year,s['name'],'headers',[(co,x['value']) for co,x in c.items() if row(co)==5 and x['value'] is not None])
 if year==2023:
  for label,rows in [('2023年次',range(23,26)),('罪名',range(32,113))]:
   z={co:x for co,x in c.items() if row(co) in rows and x['value']==0 and x['type']=='n'}
   print(label,'zeros',len(z),'formats',Counter(x['format'] for x in z.values()),'examples',list(z)[:15])
 if year>=2023:
  rows={2023:[7,11,15,19],2024:[7,11,15],2025:[7,11]}[year]
